CREATE TABLE IF NOT EXISTS dinero_import_sources (
  id INTEGER PRIMARY KEY,
  raw_sha256 TEXT NOT NULL UNIQUE CHECK(length(raw_sha256) = 64 AND raw_sha256 NOT GLOB '*[^0-9a-fA-F]*'),
  raw_size_bytes INTEGER NOT NULL CHECK(raw_size_bytes >= 0),
  canonical_listing_sha256 TEXT NOT NULL CHECK(length(canonical_listing_sha256) = 64 AND canonical_listing_sha256 NOT GLOB '*[^0-9a-fA-F]*'),
  canonical_listing_count INTEGER NOT NULL CHECK(canonical_listing_count >= 0),
  received_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(id, raw_sha256),
  UNIQUE(id, raw_sha256, canonical_listing_sha256, canonical_listing_count)
);
CREATE TABLE IF NOT EXISTS dinero_import_inventories (
  id INTEGER PRIMARY KEY, source_id INTEGER NOT NULL, source_raw_sha256 TEXT NOT NULL CHECK(length(source_raw_sha256) = 64 AND source_raw_sha256 NOT GLOB '*[^0-9a-fA-F]*'),
  canonical_listing_sha256 TEXT NOT NULL CHECK(length(canonical_listing_sha256) = 64 AND canonical_listing_sha256 NOT GLOB '*[^0-9a-fA-F]*'),
  canonical_listing_count INTEGER NOT NULL CHECK(canonical_listing_count >= 0),
  entry_count INTEGER NOT NULL CHECK(entry_count >= 0), total_size_bytes INTEGER NOT NULL CHECK(total_size_bytes >= 0),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(id, source_id, source_raw_sha256),
  FOREIGN KEY(source_id, source_raw_sha256, canonical_listing_sha256, canonical_listing_count) REFERENCES dinero_import_sources(id, raw_sha256, canonical_listing_sha256, canonical_listing_count)
);
CREATE TABLE IF NOT EXISTS dinero_import_inventory_entries (
  id INTEGER PRIMARY KEY, inventory_id INTEGER NOT NULL REFERENCES dinero_import_inventories(id),
  entry_path TEXT NOT NULL CHECK(length(entry_path) > 0 AND substr(entry_path, 1, 1) != '/' AND instr(entry_path, '..') = 0),
  entry_size_bytes INTEGER NOT NULL CHECK(entry_size_bytes >= 0),
  entry_sha256 TEXT NOT NULL CHECK(length(entry_sha256) = 64 AND entry_sha256 NOT GLOB '*[^0-9a-fA-F]*'),
  UNIQUE(inventory_id, entry_path), UNIQUE(inventory_id, entry_path, entry_sha256)
);
CREATE TABLE IF NOT EXISTS dinero_import_attempts (
  id INTEGER PRIMARY KEY, inventory_id INTEGER NOT NULL, source_id INTEGER NOT NULL, source_raw_sha256 TEXT NOT NULL CHECK(length(source_raw_sha256) = 64 AND source_raw_sha256 NOT GLOB '*[^0-9a-fA-F]*'),
  parser_contract TEXT NOT NULL CHECK(length(parser_contract) > 0), actor TEXT NOT NULL CHECK(length(actor) > 0),
  cutover_date TEXT NOT NULL CHECK(length(cutover_date) = 10),
  outcome TEXT NOT NULL CHECK(outcome IN ('accepted','rejected')),
  result_sha256 TEXT NOT NULL CHECK(length(result_sha256) = 64 AND result_sha256 NOT GLOB '*[^0-9a-fA-F]*'), recorded_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(id, inventory_id), UNIQUE(id, inventory_id, source_id, source_raw_sha256),
  FOREIGN KEY(inventory_id, source_id, source_raw_sha256) REFERENCES dinero_import_inventories(id, source_id, source_raw_sha256)
);
CREATE TABLE IF NOT EXISTS dinero_import_archive_evidence (
  id INTEGER PRIMARY KEY, attempt_id INTEGER NOT NULL, inventory_id INTEGER NOT NULL, source_id INTEGER NOT NULL, source_raw_sha256 TEXT NOT NULL CHECK(length(source_raw_sha256) = 64 AND source_raw_sha256 NOT GLOB '*[^0-9a-fA-F]*'),
  fiscal_year INTEGER NOT NULL CHECK(fiscal_year BETWEEN 1 AND 9999), archive_sha256 TEXT NOT NULL CHECK(length(archive_sha256) = 64 AND archive_sha256 NOT GLOB '*[^0-9a-fA-F]*'),
  archive_size_bytes INTEGER NOT NULL CHECK(archive_size_bytes >= 0), UNIQUE(attempt_id, fiscal_year),
  FOREIGN KEY(attempt_id, inventory_id, source_id, source_raw_sha256) REFERENCES dinero_import_attempts(id, inventory_id, source_id, source_raw_sha256)
);
CREATE UNIQUE INDEX IF NOT EXISTS idx_documents_id_sha256_hash ON documents(id, sha256_hash);
CREATE TABLE IF NOT EXISTS dinero_import_document_links (
  id INTEGER PRIMARY KEY, attempt_id INTEGER NOT NULL, inventory_id INTEGER NOT NULL, entry_path TEXT NOT NULL, entry_sha256 TEXT NOT NULL CHECK(length(entry_sha256) = 64 AND entry_sha256 NOT GLOB '*[^0-9a-fA-F]*'),
  document_id INTEGER NOT NULL REFERENCES documents(id), journal_entry_id INTEGER REFERENCES journal_entries(id), voucher_reference TEXT,
  disposition TEXT NOT NULL CHECK(disposition IN ('linked','unmatched','excluded')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(attempt_id, entry_path, entry_sha256),
  FOREIGN KEY(attempt_id, inventory_id) REFERENCES dinero_import_attempts(id, inventory_id),
  FOREIGN KEY(inventory_id, entry_path, entry_sha256) REFERENCES dinero_import_inventory_entries(inventory_id, entry_path, entry_sha256),
  FOREIGN KEY(document_id, entry_sha256) REFERENCES documents(id, sha256_hash)
);
CREATE INDEX IF NOT EXISTS idx_dinero_import_inventory_entries_inventory ON dinero_import_inventory_entries(inventory_id, entry_path);
CREATE INDEX IF NOT EXISTS idx_dinero_import_archive_evidence_attempt ON dinero_import_archive_evidence(attempt_id, fiscal_year);
CREATE INDEX IF NOT EXISTS idx_dinero_import_document_links_document ON dinero_import_document_links(document_id);
